-- 0240_provider_capabilities.sql
-- M0 (provider abstraction) — Capability matrix per (provider, model).
--
-- Fonte unica di verita per i parametri per-modello che erano hardcoded nei
-- provider Python: max_tokens risposta, tool_choice, dialetto schema, formato
-- tool_call, cache prompt, timeout, soglie soft-failure, compaction history,
-- limiti tool_result. Regola G del CLAUDE.md: nessun fallback hardcoded; se
-- manca la riga per un (provider, model) attivo, mcp-core panica all avvio.
--
-- Schema e dati derivati dallo stato applicato in produzione (ricostruzione
-- post perdita del codice: il DB conservava lo schema, le migrazioni no).
-- Idempotente: CREATE IF NOT EXISTS + INSERT ON CONFLICT DO NOTHING.

CREATE TABLE IF NOT EXISTS nexus_provider_capabilities (
    provider text NOT NULL,
    model text NOT NULL,
    tool_use boolean DEFAULT false NOT NULL,
    vision boolean DEFAULT false NOT NULL,
    thinking boolean DEFAULT false NOT NULL,
    max_context_tokens integer DEFAULT 8192 NOT NULL,
    default_max_output_tokens integer DEFAULT 4096 NOT NULL,
    max_output_tokens_hard integer DEFAULT 16384 NOT NULL,
    tool_choice_style text DEFAULT 'openai_auto'::text NOT NULL,
    tool_choice_first_turn_force boolean DEFAULT false NOT NULL,
    schema_strict boolean DEFAULT false NOT NULL,
    schema_dialect text DEFAULT 'openai_loose'::text NOT NULL,
    tool_call_format text DEFAULT 'openai_delta'::text NOT NULL,
    max_tools_in_request integer,
    supports_prompt_cache boolean DEFAULT false NOT NULL,
    prompt_cache_dialect text,
    supports_parallel_tools boolean DEFAULT true NOT NULL,
    stop_reason_dialect text DEFAULT 'openai_finish_reason'::text NOT NULL,
    soft_failure_iter_threshold integer DEFAULT 3 NOT NULL,
    soft_failure_content_threshold integer DEFAULT 800 NOT NULL,
    history_keep_recent_messages integer DEFAULT 12 NOT NULL,
    history_max_old_tool_result_chars integer DEFAULT 2000 NOT NULL,
    request_timeout_seconds integer DEFAULT 60 NOT NULL,
    connect_timeout_seconds integer DEFAULT 10 NOT NULL,
    tool_result_max_chars integer DEFAULT 6000 NOT NULL,
    tool_result_max_bytes integer DEFAULT 512000 NOT NULL,
    tool_result_max_lines integer DEFAULT 2000 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT chk_prompt_cache_dialect CHECK (((prompt_cache_dialect IS NULL) OR (prompt_cache_dialect = 'anthropic_ephemeral'::text))),
    CONSTRAINT chk_schema_dialect CHECK ((schema_dialect = ANY (ARRAY['anthropic'::text, 'openai_strict'::text, 'openai_loose'::text, 'google_function_declaration'::text]))),
    CONSTRAINT chk_stop_reason_dialect CHECK ((stop_reason_dialect = ANY (ARRAY['anthropic'::text, 'openai_finish_reason'::text, 'google_inferred'::text]))),
    CONSTRAINT chk_tool_call_format CHECK ((tool_call_format = ANY (ARRAY['native_blocks'::text, 'openai_delta'::text, 'google_function_call'::text, 'xml_inline_fallback'::text]))),
    CONSTRAINT chk_tool_choice_style CHECK ((tool_choice_style = ANY (ARRAY['openai_required'::text, 'openai_auto'::text, 'anthropic_any'::text, 'google_function_calling_any'::text, 'none'::text]))),
    CONSTRAINT nexus_provider_capabilities_pkey PRIMARY KEY (provider, model)
);
CREATE INDEX IF NOT EXISTS idx_nexus_provider_capabilities_provider ON nexus_provider_capabilities USING btree (provider);

-- ── Dati calibrati in produzione (ricostruzione fedele) ──────────────────────
